namespace YoutubeDl.Engine.Media;

public static partial class FfmpegTool
{
    private static async Task<string> BridgeAv1DolbyAsync(string ffmpeg,string input,string directory,int index,ProbedStream source,CancellationToken ct,bool nativeCompression=false)
    {
        if(nativeCompression){if(source.Dolby is not {Profile:10,Compatibility:1 or 4,Rpu:1,Base:1,Enhancement:0,Major:1,Minor:0,Compression:"none" or "" or "limited" or "extended"})throw new NotSupportedException("Native AV1 Dolby expansion requires a complete compatible profile-10 configuration.");}else source.Dolby!.Validate(source.ColorTransfer,true);var expanded=Path.Combine(directory,"spatial-av1-expanded-"+index+".mp4");await RunAsync(ffmpeg,["-y","-v","error","-i",input,"-map","0:v:0","-c","copy",..(nativeCompression?Array.Empty<string>():new[]{"-bsf:v","dovi_rpu=compression=none"}),"-strict","unofficial",expanded],ct,rejectDiagnostics:true).ConfigureAwait(false);var streams=await ProbeStreamsAsync(ffmpeg,expanded,ct,"inspect AV1 Dolby bridge",localMediaOnly:true).ConfigureAwait(false);if(streams.Count!=1)throw new InvalidDataException("Invalid AV1 bridge stream count.");var frames=await ReadHdrFramesAsync(ffmpeg,expanded,streams[0],new(){Broader=true},ct).ConfigureAwait(false);var bindings=frames.ToDictionary(frame=>frame.PacketPosition);var assigned=new HashSet<long>();
        await InspectHdrPacketsAsync(ffmpeg,expanded,(position,rpus)=>{if(rpus.Count!=1||!bindings.TryGetValue(position,out var frame)||!assigned.Add(position))throw new NotSupportedException("AV1 Dolby requires one complete independent RPU and one decoded picture per coded sample.");frame.DolbyPayload=rpus[0];},ct,true,nativeCompression?new DolbyRpuSequence(source.Dolby!.Compression is "limited" or "extended",source.Dolby.Compression=="extended"):null).ConfigureAwait(false);if(assigned.Count!=frames.Count)throw new InvalidDataException("AV1 Dolby packet/picture inventory is incomplete.");
        var span=frames[^1].Time+frames[^1].Duration-frames[0].Time;var edit=new MediaPeriodEdit(span,0,span);var projected=HdrMetadataTimeline.Project(frames,edit);var encoded=Path.Combine(directory,"spatial-av1-base-"+index+".mp4");await EncodeSpatialAsync(ffmpeg,expanded,encoded,"setpts=PTS-STARTPTS,setsar=1,fps=30",streams[0],false,frames[0].Metadata.Static,ct).ConfigureAwait(false);var raw=Path.Combine(directory,"spatial-av1-base-"+index+".hevc");await RunAsync(ffmpeg,["-y","-v","error","-i",encoded,"-map","0:v:0","-c","copy","-bsf:v","hevc_mp4toannexb,hevc_metadata=aud=insert","-f","hevc",raw],ct,rejectDiagnostics:true).ConfigureAwait(false);var patched=Path.Combine(directory,"spatial-av1-rpu-"+index+".hevc");await HevcMetadataTransport.PatchAsync(raw,patched,projected,ct).ConfigureAwait(false);var output=Path.Combine(directory,"spatial-av1-bridge-"+index+".mp4");await RunAsync(ffmpeg,["-y","-v","error","-fflags","+genpts","-r","30","-f","hevc","-i",patched,"-c","copy","-tag:v","hvc1",output],ct,rejectDiagnostics:true).ConfigureAwait(false);await Mp4DolbyConfiguration.CopyAsync(expanded,output,ct,source.Width,source.Height,8,uncompressed:nativeCompression).ConfigureAwait(false);return output;
    }
}
